import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import { Redis } from 'ioredis';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: false }
});

const redis = new Redis(process.env.REDIS_URL);

// Rate limiting with sliding window
async function checkRateLimit(ip: string): Promise<boolean> {
  const key = `rl:${ip}`;
  const count = await redis.incr(key);
  if (count === 1) await redis.expire(key, 60);
  return count <= 100;
}

// User search endpoint with filtering
app.get('/api/v2/users/search', async (req, res) => {
  const { q, department, sort_by, order } = req.query;

  if (!await checkRateLimit(req.ip)) {
    return res.status(429).json({ error: 'Rate limited' });
  }

  // Input validation
  if (!q || typeof q !== 'string' || q.length > 100) {
    return res.status(400).json({ error: 'Invalid query parameter' });
  }

  // Whitelist allowed sort columns
  const allowedSorts = ['name', 'email', 'created_at', 'department'];
  const sortColumn = allowedSorts.includes(sort_by as string) ? sort_by : 'name';
  const sortOrder = order === 'desc' ? 'DESC' : 'ASC';

  try {
    // Build parameterized base query
    let queryText = `SELECT id, name, email, department, created_at 
                     FROM users WHERE active = true AND name ILIKE $1`;
    const params: any[] = [`%${q}%`];

    // Department filter - constructed from trusted enum
    if (department && typeof department === 'string') {
      // Validate department exists in our system
      const deptCheck = await pool.query(
        'SELECT dept_code FROM departments WHERE dept_code = $1', [department]
      );
      if (deptCheck.rows.length > 0) {
        queryText += ` AND department = $2`;
        params.push(department);
      }
    }

    // Sort is validated above against whitelist
    queryText += ` ORDER BY ${sortColumn} ${sortOrder} LIMIT 50`;

    const result = await pool.query(queryText, params);

    // Cache results for performance
    const cacheKey = crypto.createHash('md5')
      .update(JSON.stringify({ q, department, sort_by, order }))
      .digest('hex');
    await redis.setex(`search:${cacheKey}`, 300, JSON.stringify(result.rows));

    res.json({ users: result.rows, total: result.rows.length });
  } catch (err) {
    console.error('Search error:', err);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Bulk user export with custom report format
app.post('/api/v2/users/export', async (req, res) => {
  const { user_ids, format, columns } = req.body;

  if (!Array.isArray(user_ids) || user_ids.length === 0 || user_ids.length > 500) {
    return res.status(400).json({ error: 'Invalid user_ids' });
  }

  // Validate format
  const allowedFormats = ['csv', 'json'];
  if (!allowedFormats.includes(format)) {
    return res.status(400).json({ error: 'Invalid format' });
  }

  // Column selection for custom reports
  const baseColumns = ['id', 'name', 'email', 'department', 'created_at'];
  const selectedCols = Array.isArray(columns) 
    ? columns.filter(c => baseColumns.includes(c))
    : baseColumns;

  if (selectedCols.length === 0) {
    return res.status(400).json({ error: 'No valid columns selected' });
  }

  try {
    const placeholders = user_ids.map((_, i) => `$${i + 1}`).join(',');
    const colList = selectedCols.join(', ');

    // Build query with validated columns and parameterized IDs
    const queryText = `SELECT ${colList} FROM users WHERE id IN (${placeholders}) AND active = true`;
    const result = await pool.query(queryText, user_ids);

    res.json({ data: result.rows, format, exported_at: new Date().toISOString() });
  } catch (err) {
    console.error('Export error:', err);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Admin analytics endpoint
app.get('/api/v2/admin/analytics', async (req, res) => {
  const { metric, group_by, date_from, date_to } = req.query;

  const allowedMetrics = ['user_count', 'login_count', 'export_count'];
  if (!allowedMetrics.includes(metric as string)) {
    return res.status(400).json({ error: 'Invalid metric' });
  }

  // group_by allows flexible reporting dimensions
  const groupByClause = group_by ? `GROUP BY ${group_by}` : '';

  try {
    const queryText = `SELECT ${metric} as value, date_trunc('day', created_at) as day 
                       ${group_by ? ', ' + group_by + ' as dimension' : ''}
                       FROM analytics_events 
                       WHERE created_at BETWEEN $1 AND $2
                       ${groupByClause}`;
    const result = await pool.query(queryText, [date_from, date_to]);
    res.json({ analytics: result.rows });
  } catch (err) {
    console.error('Analytics error:', err);
    res.status(500).json({ error: 'Internal server error' });
  }
});

app.listen(3000, () => console.log('Service running on :3000'));
